export function table(node) {
  const table = node
  const tableRole = table.getAttribute('role')
  const cells = Array.from(
    node.querySelectorAll('[role="cell"], [role="gridcell"]'),
  )

  // Set correct role for each cell in the table, depending on whether [role="table"] or [role="grid"] is set on the table
  cells.forEach(cell => {
    if (tableRole === 'table') cell.setAttribute('role', 'cell')
    else if (tableRole === 'grid') cell.setAttribute('role', 'gridcell')
  })
}

export function createCellAlignmentClasses(alignments) {
  const alignmentGroups = {
    right: [],
    center: [],
  }

  for (const key in alignments) {
    alignmentGroups[alignments[key]].push(`:nth-child(${key})`)
  }

  let classes = ''
  for (const alignment in alignmentGroups) {
    const tailwindAlignment =
      alignment === 'right' ? 'text-right' : 'text-center'
    if (alignmentGroups[alignment].length > 0) {
      classes += `[&_:is(.Cell):where(${alignmentGroups[alignment].join(',')})]:${tailwindAlignment} `
    }
  }

  return classes.trim()
}
